#!/usr/bin/env bash
# IKS Website — รูปประเภทธุรกิจ 3 หมวด (ค้าปลีกและ SME / หลังคาไฟเบอร์ / รถคอก) + เผยแพร่ · รันซ้ำได้
if [ "${BASH_SOURCE[0]:-$0}" != "$0" ]; then echo "กรุณารันด้วย: bash ${BASH_SOURCE[0]}"; return 1 2>/dev/null || exit 1; fi
set -euo pipefail
SELF="$(readlink -f "$0")"
DEST=/var/www/ikssa-media/industries
mkdir -p "$DEST"
sed -n '/^__ARCHIVE_BELOW__$/,$p' "$SELF" | tail -n +2 | base64 -d | tar -xz --no-same-owner -C "$DEST"
chmod 755 "$DEST"; chmod 644 "$DEST"/*.webp
echo "✔ คัดลอกรูปแล้ว"
docker exec -i iks-web-db psql -q -U iks_owner -d iks_web -v ON_ERROR_STOP=1 <<'SQL'
set client_min_messages = warning;
-- รองรับหลายรูป (ถ้ายังไม่ได้ติดตั้งเว็บ v6)
alter table public.industries add column if not exists gallery jsonb not null default '[]'::jsonb;
create or replace view public.published_industries as select * from public.industries where status = 'published' and is_visible;
begin;
insert into public.media_files (path, original_name, mime_type, size_bytes, width, height, alt_text) values
  ('industries/industry-alu-1.webp', 'industry-alu-1.webp', 'image/webp', 216212, 1200, 900, 'รถอีซูซุ ค้าปลีกและ SME'),
  ('industries/industry-alu-2.webp', 'industry-alu-2.webp', 'image/webp', 144968, 1200, 900, 'รถอีซูซุ ค้าปลีกและ SME'),
  ('industries/industry-alu-3.webp', 'industry-alu-3.webp', 'image/webp', 154586, 1200, 900, 'รถอีซูซุ ค้าปลีกและ SME'),
  ('industries/industry-alu-4.webp', 'industry-alu-4.webp', 'image/webp', 242302, 1200, 900, 'รถอีซูซุ ค้าปลีกและ SME'),
  ('industries/industry-fiber-1.webp', 'industry-fiber-1.webp', 'image/webp', 173674, 1200, 900, 'รถอีซูซุ หลังคาไฟเบอร์'),
  ('industries/industry-fiber-2.webp', 'industry-fiber-2.webp', 'image/webp', 185570, 1200, 900, 'รถอีซูซุ หลังคาไฟเบอร์'),
  ('industries/industry-fiber-3.webp', 'industry-fiber-3.webp', 'image/webp', 223238, 1200, 900, 'รถอีซูซุ หลังคาไฟเบอร์'),
  ('industries/industry-kok-1.webp', 'industry-kok-1.webp', 'image/webp', 219324, 1200, 900, 'รถอีซูซุ รถคอก'),
  ('industries/industry-kok-2.webp', 'industry-kok-2.webp', 'image/webp', 246664, 1200, 900, 'รถอีซูซุ รถคอก')
on conflict (path) do nothing;
insert into public.industries (name, subtitle, status, sort_order) select 'ค้าปลีกและ SME', 'ร้านค้า กระจายสินค้า ธุรกิจขนาดเล็ก–กลาง', 'draft', 90 where not exists (select 1 from public.industries where name = 'ค้าปลีกและ SME');
update public.industries set image = 'industries/industry-alu-1.webp', gallery = '["industries/industry-alu-2.webp", "industries/industry-alu-3.webp", "industries/industry-alu-4.webp"]'::jsonb, status = 'published' where name = 'ค้าปลีกและ SME';
insert into public.industries (name, subtitle, status, sort_order) select 'หลังคาไฟเบอร์', 'หลังคาสูง กันแดดกันฝน ปกป้องสินค้า', 'draft', 90 where not exists (select 1 from public.industries where name = 'หลังคาไฟเบอร์');
update public.industries set image = 'industries/industry-fiber-1.webp', gallery = '["industries/industry-fiber-2.webp", "industries/industry-fiber-3.webp"]'::jsonb, status = 'published' where name = 'หลังคาไฟเบอร์';
insert into public.industries (name, subtitle, status, sort_order) select 'รถคอก', 'คอกเหล็ก คอกสูง บรรทุกสินค้าเกษตรและของชิ้นใหญ่', 'draft', 90 where not exists (select 1 from public.industries where name = 'รถคอก');
update public.industries set image = 'industries/industry-kok-1.webp', gallery = '["industries/industry-kok-2.webp"]'::jsonb, status = 'published' where name = 'รถคอก';
update public.industries i set sort_order = v.o from (values
  ('โลจิสติกส์',10),('ห้องเย็น',20),('ธุรกิจอาหาร',30),('ก่อสร้าง',40),('รถคอก',50),('ค้าปลีกและ SME',60),('หลังคาไฟเบอร์',70)) as v(n,o)
 where i.name = v.n;
commit;
\pset footer off
select name as "ประเภท", status as "สถานะ", (case when image is null then 0 else 1 end) + jsonb_array_length(gallery) as "จำนวนรูป" from public.industries order by sort_order;
SQL
echo; echo "✔ เสร็จแล้ว — ดูได้ที่ https://ikssa.io/admin/preview?to=/commercial"
exit 0
